-- ----------------------------------------------------------------------------
-- Users: Login identities for the demo (stub auth).
-- ----------------------------------------------------------------------------
CREATE TABLE users (
  user_id                             TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  email                               TEXT                ,
  role                                TEXT                ,                     -- coordinator | bride | groom
  display_name                        TEXT                
);
COMMENT ON TABLE users IS 'Login identities for the demo (stub auth).';
COMMENT ON COLUMN users.role IS 'coordinator | bride | groom';

-- ----------------------------------------------------------------------------
-- Tables: Physical reception tables. Guests are assigned to one Table each.
-- ----------------------------------------------------------------------------
CREATE TABLE tables (
  table_id                            TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  label                               TEXT                ,                     -- Friendly label e.g. 'Head Table', 'Cousins'.
  seats                               INTEGER                                   -- Physical capacity.
);
COMMENT ON TABLE tables IS 'Physical reception tables. Guests are assigned to one Table each.';
COMMENT ON COLUMN tables.label IS 'Friendly label e.g. ''Head Table'', ''Cousins''.';
COMMENT ON COLUMN tables.seats IS 'Physical capacity.';

-- ----------------------------------------------------------------------------
-- Guests: Wedding guests. Each is assigned to one Table.
-- ----------------------------------------------------------------------------
CREATE TABLE guests (
  guest_id                            TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  full_name                           TEXT                ,
  side                                TEXT                ,                     -- bride | groom | both
  dietary                             TEXT                ,                     -- none | veg | vegan | gf | kosher
  language                            TEXT                ,                     -- en | es | fr
  age_band                            TEXT                ,                     -- child | adult | senior
  assigned_table                      TEXT                                      -- FK to Tables.TableId. Editable — moves the guest.
);
COMMENT ON TABLE guests IS 'Wedding guests. Each is assigned to one Table.';
COMMENT ON COLUMN guests.side IS 'bride | groom | both';
COMMENT ON COLUMN guests.dietary IS 'none | veg | vegan | gf | kosher';
COMMENT ON COLUMN guests.language IS 'en | es | fr';
COMMENT ON COLUMN guests.age_band IS 'child | adult | senior';
COMMENT ON COLUMN guests.assigned_table IS 'FK to Tables.TableId. Editable — moves the guest.';

-- ----------------------------------------------------------------------------
-- Relationships: Directed-but-symmetric guest-pair affinities. Kind is loves | prefers | avoid | must-not, with a Weight (positive = affinity, negative = friction).
-- ----------------------------------------------------------------------------
CREATE TABLE relationships (
  rel_id                              TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  guest_a                             TEXT                ,
  guest_b                             TEXT                ,
  kind                                TEXT                ,                     -- loves | prefers | avoid | must-not
  weight                              NUMERIC                                   -- Signed magnitude (positive = wants near, negative = wants apart).
);
COMMENT ON TABLE relationships IS 'Directed-but-symmetric guest-pair affinities. Kind is loves | prefers | avoid | must-not, with a Weight (positive = affinity, negative = friction).';
COMMENT ON COLUMN relationships.kind IS 'loves | prefers | avoid | must-not';
COMMENT ON COLUMN relationships.weight IS 'Signed magnitude (positive = wants near, negative = wants apart).';

-- ============================================================================
-- FK INDEXES - Performance only, always applied
-- ============================================================================

-- Guests
CREATE INDEX IF NOT EXISTS idx_guests_assigned_table ON guests (assigned_table);

-- Relationships
CREATE INDEX IF NOT EXISTS idx_relationships_guest_a ON relationships (guest_a);
CREATE INDEX IF NOT EXISTS idx_relationships_guest_b ON relationships (guest_b);

